function validate([grid]) {
  const n = grid.length;
  if (n < 1 || n > 50) return 'n must be between 1 and 50.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square: every row has n cells.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 50)) return 'Each height is a whole number from 0 to 50.';
  }
  return null;
}

