function projectionArea(grid) {
  // Build every cube, then mark the squares each of the three shadows covers.
  const n = grid.length;
  const top = new Set(), front = new Set(), side = new Set();
  for (let x = 0; x < n; x++) {
    for (let y = 0; y < n; y++) {
      for (let z = 0; z < grid[x][y]; z++) {
        top.add(x + ',' + y);
        front.add(y + ',' + z);
        side.add(x + ',' + z);
      }
    }
  }
  return top.size + front.size + side.size;
}

