function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 4);
  const maxHeight = size === 'large' ? 50 : 1 + Math.floor(rand() * 5);
  const zeroChance = rand() * 0.6;
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < zeroChance ? 0 : Math.floor(rand() * (maxHeight + 1)))));
  return [grid];
}
